#include <string>
#include <algorithm>

class Solution {
public:
    long long nextSpecialPalindrome(long long n) {
        long long cur = n + 1;
        while (true) {
            std::string s = std::to_string(cur);
            int len = s.size();
            int half = len / 2;
            std::string left = s.substr(0, len - half);
            std::string pal = left;
            for (int i = half - 1; i >= 0; --i) {
                pal.push_back(left[i]);
            }
            long long cand = std::stoll(pal);
            if (cand > n) {
                return cand;
            }
            long long left_val = std::stoll(left) + 1;
            std::string next_left = std::to_string(left_val);
            while ((int)next_left.size() < len) next_left.push_back('0');
            cur = std::stoll(next_left);
        }
    }
};

class Solution {
    public long nextSpecialPalindrome(long n) {
        long cur = n + 1;
        while (true) {
            String s = String.valueOf(cur);
            int len = s.length();
            int half = len / 2;
            String left = s.substring(0, len - half);
            StringBuilder sb = new StringBuilder(left);
            for (int i = half - 1; i >= 0; i--) {
                sb.append(left.charAt(i));
            }
            long cand = Long.parseLong(sb.toString());
            if (cand > n) {
                return cand;
            }
            long leftVal = Long.parseLong(left) + 1;
            String nextLeft = String.valueOf(leftVal);
            while (nextLeft.length() < len) {
                nextLeft = nextLeft + "0";
            }
            cur = Long.parseLong(nextLeft);
        }
    }
}

